
(function(){
 const KEY='liftAdminDetalV1';
 const saved=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')}catch(e){return {}}};
 const persist=o=>localStorage.setItem(KEY,JSON.stringify(o));
 function applySaved(){const o=saved();for(const p of PRODUCTS){const x=o[String(p.id)];if(x)Object.assign(p,x)}if(typeof render==='function')render();if(typeof renderCart==='function')renderCart()}
 window.openLiftAdmin=function(){document.getElementById('liftAdminPanel').classList.add('open');document.getElementById('liftAdminBackdrop').classList.add('open');document.body.style.overflow='hidden';renderLiftAdmin()}
 window.closeLiftAdmin=function(){document.getElementById('liftAdminPanel').classList.remove('open');document.getElementById('liftAdminBackdrop').classList.remove('open');document.body.style.overflow=''}
 function moneyInput(v){return Number(v||0).toLocaleString('es-CO')}
 function parseMoney(v){return Number(String(v||'').replace(/[^0-9]/g,''))||0}
 window.renderLiftAdmin=function(){const q=norm(document.getElementById('liftAdminSearch')?.value||'');const arr=PRODUCTS.filter(p=>!q||norm([p.name,p.brand,p.category].join(' ')).includes(q));document.getElementById('liftAdminCount').textContent=`${arr.length} productos · precio detal`;document.getElementById('liftAdminList').innerHTML=arr.slice(0,500).map(p=>`<div class="liftAdminRow"><img src="${p.image||''}" alt=""><div><div class="liftAdminName">${esc(p.name)}</div><div class="liftAdminMeta">${esc(p.brand||'')} · ${esc(p.category||'')}</div></div><input class="liftAdminPrice" id="adminPrice_${p.id}" inputmode="numeric" value="${moneyInput(p.price)}" onfocus="this.value=String(this.value).replace(/[^0-9]/g,'')" onblur="this.value=Number(String(this.value).replace(/[^0-9]/g,'')||0).toLocaleString('es-CO')"><button class="liftAdminSave" title="Guardar precio" onclick="saveLiftRetailPrice(${JSON.stringify(p.id)},this)">✓</button></div>`).join('')+(arr.length>500?`<div class="liftAdminCount">Mostrando 500. Usa el buscador para encontrar los demás.</div>`:'')}
 window.saveLiftRetailPrice=function(id,btn){const p=PRODUCTS.find(x=>String(x.id)===String(id));if(!p)return;const input=document.getElementById('adminPrice_'+id);const price=parseMoney(input.value);p.price=price;const o=saved();o[String(id)]={...(o[String(id)]||{}),price};persist(o);input.value=moneyInput(price);btn.classList.add('liftAdminSaved');setTimeout(()=>btn.classList.remove('liftAdminSaved'),700);if(typeof render==='function')render();if(typeof renderCart==='function')renderCart()}
 window.openLiftAdminEditor=function(id){const p=id!=null?PRODUCTS.find(x=>String(x.id)===String(id)):null;const e=document.getElementById('liftAdminEditor');e.classList.add('open');e.innerHTML=`<div class="liftAdminGrid"><div class="liftAdminField full"><label>Nombre</label><input id="laName" value="${esc(p?.name||'')}"></div><div class="liftAdminField"><label>Marca</label><input id="laBrand" value="${esc(p?.brand||'')}"></div><div class="liftAdminField"><label>Categoría</label><input id="laCat" value="${esc(p?.category||'')}"></div><div class="liftAdminField"><label>Precio detal</label><input id="laPrice" inputmode="numeric" value="${p?moneyInput(p.price):''}"></div><div class="liftAdminField"><label>Imagen URL</label><input id="laImage" value="${esc(p?.image||'')}"></div></div><div class="liftAdminEditorActions"><button class="liftAdminPrimary" onclick="saveLiftAdminProduct(${p?JSON.stringify(p.id):'null'})">Guardar</button><button class="liftAdminCancel" onclick="document.getElementById('liftAdminEditor').classList.remove('open')">Cancelar</button></div>`;e.scrollIntoView({behavior:'smooth',block:'nearest'})}
 window.saveLiftAdminProduct=function(id){const data={name:document.getElementById('laName').value.trim(),brand:document.getElementById('laBrand').value.trim(),category:document.getElementById('laCat').value.trim(),price:parseMoney(document.getElementById('laPrice').value),image:document.getElementById('laImage').value.trim()};if(!data.name||!data.price)return alert('Pon nombre y precio detal.');let p;if(id==null){let max=PRODUCTS.reduce((m,x)=>Math.max(m,Number(x.id)||0),0);p={id:max+1,...data};PRODUCTS.push(p)}else{p=PRODUCTS.find(x=>String(x.id)===String(id));if(!p)return;Object.assign(p,data)}const o=saved();o[String(p.id)]={...(o[String(p.id)]||{}),...data};persist(o);if(!cats.includes(data.category))cats.push(data.category);if(!brands.includes(data.brand))brands.push(data.brand);document.getElementById('liftAdminEditor').classList.remove('open');renderLiftAdmin();render();renderCart()}
 window.exportLiftAdminCSV=function(){const rows=[['ID','Producto','Marca','Categoria','Precio detal'],...PRODUCTS.map(p=>[p.id,p.name,p.brand,p.category,p.price])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='lift-precios-detal.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
 function addButton(){const bar=document.querySelector('.top .bar');if(!bar||document.getElementById('liftAdminBtn'))return;const b=document.createElement('button');b.id='liftAdminBtn';b.type='button';b.textContent='⚙ Administrar';b.onclick=openLiftAdmin;const cart=bar.querySelector('.cartDesktop');bar.insertBefore(b,cart||null)}
 applySaved();if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',addButton);else addButton();
})();
